var i={Bl\u00E1zen:["Co m\u016F\u017Ee\u0161 vyzkou\u0161et bez velk\xE9 s\xE1zky?","Ud\u011Blej mal\xFD zku\u0161ebn\xED krok a p\u0159edem si ur\u010Di, kde se zastav\xED\u0161."],M\u00E1g:["Kter\xFD n\xE1stroj u\u017E m\xE1\u0161 po ruce?","Pou\u017Eij jednu dovednost na konkr\xE9tn\xED rozpracovan\xFD \xFAkol m\xEDsto hled\xE1n\xED dal\u0161\xEDho n\xE1vodu."],Velekn\u011B\u017Eka:["Co tu\u0161\xED\u0161 a co zat\xEDm opravdu v\xED\u0161?","Zapi\u0161 si sv\u016Fj dojem a jednu ot\xE1zku, kterou ho m\u016F\u017Ee\u0161 ov\u011B\u0159it."],C\u00EDsa\u0159ovna:["Co pot\u0159ebuje pravidelnou p\xE9\u010Di?","V\u011Bnuj deset minut n\u011B\u010Demu, co chce\u0161 dlouhodob\u011B rozv\xEDjet, bez tlaku na okam\u017Eit\xFD v\xFDsledek."],C\u00EDsa\u0159:["Kde ti chyb\xED jasn\xE1 dohoda?","Pojmenuj jednu hranici a zp\u016Fsob, jak ji srozumiteln\u011B sd\u011Blit."],Velekn\u011Bz:["Kter\xE9 pravidlo p\u0159ij\xEDm\xE1\u0161 jen ze zvyku?","U jednoho b\u011B\u017En\xE9ho postupu si p\u0159ipome\u0148 jeho \xFA\u010Del. Rozhodni, zda ti je\u0161t\u011B pom\xE1h\xE1."],Milenci:["Je tvoje volba v souladu s t\xEDm, na \u010Dem ti z\xE1le\u017E\xED?","U jednoho rozhodnut\xED pojmenuj vlastn\xED pot\u0159ebu a zjisti pohled druh\xE9ho p\u0159\xEDmo rozhovorem."],V\u016Fz:["Kter\xFDm sm\u011Brem chce\u0161 opravdu jet?","Vyber jeden c\xEDl pro dne\u0161ek a odlo\u017E \xFAkol, kter\xFD t\u011B t\xE1hne opa\u010Dn\u011B."],S\u00EDla:["Kde m\u016F\u017Ee pomoci klidn\u011Bj\u0161\xED reakce?","P\u0159ed odpov\u011Bd\xED na nep\u0159\xEDjemnou zpr\xE1vu si nech kr\xE1tkou pauzu a pak napi\u0161 jednu v\u011Bcnou v\u011Btu."],Poustevn\u00EDk:["Na co pot\u0159ebuje\u0161 vlastn\xED neru\u0161en\xFD n\xE1zor?","Odlo\u017E na chv\xEDli ciz\xED doporu\u010Den\xED a sepi\u0161 si t\u0159i vlastn\xED post\u0159ehy."],"Kolo \u0161t\u011Bst\xED":["Co se m\u011Bn\xED bez tv\xE9ho p\u0159i\u010Din\u011Bn\xED?","Odd\u011Bl jednu v\u011Bc, kterou nem\xE1\u0161 v rukou, od jednoho kroku, kter\xFD ovlivnit m\u016F\u017Ee\u0161."],Spravedlnost:["M\xE1\u0161 pro sv\xE9 rozhodnut\xED stejn\xE9 m\u011B\u0159\xEDtko?","P\u0159ed z\xE1v\u011Brem si ov\u011B\u0159 jeden d\u016Fle\u017Eit\xFD \xFAdaj a p\u0159ipome\u0148 si i sv\u016Fj d\xEDl odpov\u011Bdnosti."],Viselec:["Jak by situace vypadala z jin\xE9ho m\xEDsta?","P\u0159epi\u0161 sv\u016Fj probl\xE9m jednou v\u011Btou z pohledu n\u011Bkoho dal\u0161\xEDho. Nemus\xED\u0161 s n\xEDm souhlasit."],Smrt:["Co u\u017E splnilo sv\u016Fj \xFA\u010Del?","Uzav\u0159i jednu drobnou dokon\u010Denou z\xE1le\u017Eitost a uvolni j\xED zabran\xE9 m\xEDsto. Karta nep\u0159edpov\xEDd\xE1 \xFAmrt\xED."],M\u00EDrnost:["Co pot\u0159ebuje lep\u0161\xED pom\u011Br?","Uprav jednu dne\u0161n\xED \u010Dinnost tak, aby vedle v\xFDkonu zbyl i prostor na odpo\u010Dinek."],\u010E\u00E1bel:["Kter\xFD zvyk ti bere mo\u017Enost volby?","V\u0161imni si jednoho automatick\xE9ho nutk\xE1n\xED a p\u0159ed reakc\xED si nech prostor zvolit jin\xFD postup."],V\u011B\u017E:["Kter\xFD p\u0159edpoklad si pot\u0159ebuje\u0161 ov\u011B\u0159it?","P\u0159ezkoumej jednu domn\u011Bnku a najdi pevn\xFD fakt, o kter\xFD se m\u016F\u017Ee\u0161 op\u0159\xEDt. Nemus\xED\u0161 nic bo\u0159it."],Hv\u011Bzda:["O co se m\u016F\u017Ee\u0161 op\u0159\xEDt pr\xE1v\u011B te\u010F?","P\u0159ipome\u0148 si jednu v\u011Bc, kter\xE1 se v posledn\xED dob\u011B poda\u0159ila, a navazuj\xEDc\xED mal\xFD krok."],Luna:["Kde zam\u011B\u0148uje\u0161 obavu za skute\u010Dnost?","Rozd\u011Bl si situaci do dvou sloupc\u016F: co v\xED\u0161 a co zat\xEDm odhaduje\u0161."],Slunce:["Co dnes m\u016F\u017Ee\u0161 ocenit bez srovn\xE1v\xE1n\xED?","Dop\u0159ej si chv\xEDli u konkr\xE9tn\xED radosti a \u0159ekni n\u011Bkomu, \u010Deho si na n\u011Bm v\xE1\u017E\xED\u0161."],Soud:["Co po ohl\xE9dnut\xED vid\xED\u0161 jinak?","Vra\u0165 se k jednomu star\u0161\xEDmu rozhodnut\xED a zapi\u0161, co je pro tebe dnes nav\xEDc d\u016Fle\u017Eit\xE9."],Sv\u011Bt:["Co m\u016F\u017Ee\u0161 uznat za dokon\u010Den\xE9?","U jednoho \xFAkolu pojmenuj hotov\xFD v\xFDsledek. Dal\u0161\xED vylep\u0161ov\xE1n\xED si nech a\u017E na nov\xE9 rozhodnut\xED."],"Eso hol\xED":["Kter\xFD n\xE1pad si zaslou\u017E\xED prvn\xED pokus?","Vyhra\u010F \u010Dtvrt hodiny na zkou\u0161ku n\xE1padu, kter\xFD t\u011B l\xE1k\xE1; nemus\xED\u0161 se hned zav\xE1zat k cel\xE9mu projektu."],"Dvojka hol\xED":["Mezi kter\xFDmi dv\u011Bma sm\u011Bry vyb\xEDr\xE1\u0161?","Napi\u0161 si pro ka\u017Edou mo\u017Enost jeden p\u0159\xEDnos, jednu p\u0159ek\xE1\u017Eku a nejmen\u0161\xED ov\u011B\u0159ovac\xED krok."],"Trojka hol\xED":["Na jakou odezvu pr\xE1v\u011B \u010Dek\xE1\u0161?","Zkontroluj, co u\u017E je odeslan\xE9, a domluv konkr\xE9tn\xED term\xEDn dal\u0161\xEDho kontaktu."],"\u010Cty\u0159ka hol\xED":["Co stoj\xED za to spole\u010Dn\u011B oslavit?","P\u0159ipome\u0148 lidem kolem sebe jeden spole\u010Dn\xFD pokrok, i kdy\u017E cel\xFD projekt je\u0161t\u011B nekon\u010D\xED."],"P\u011Btka hol\xED":["Je spor o c\xEDl, nebo jen o postup?","P\u0159i neshod\u011B nejprve pojmenuj spole\u010Dn\xFD c\xEDl a teprve pak porovnej r\u016Fzn\xE9 cesty."],"\u0160estka hol\xED":["Kter\xFD pokrok z\u016Fst\xE1v\xE1 bez pov\u0161imnut\xED?","Uka\u017E jeden konkr\xE9tn\xED v\xFDsledek a oce\u0148 tak\xE9 lidi, kte\u0159\xED k n\u011Bmu p\u0159isp\u011Bli."],"Sedmi\u010Dka hol\xED":["Co chce\u0161 h\xE1jit a co u\u017E nemus\xED\u0161 vysv\u011Btlovat?","Vyber jednu d\u016Fle\u017Eitou hranici a sd\u011Bl ji stru\u010Dn\u011B, bez dal\u0161\xEDch kol obhajov\xE1n\xED."],"Osmi\u010Dka hol\xED":["Co pot\u0159ebuje rychlou, jasnou zpr\xE1vu?","Vy\u0159i\u010F jeden kr\xE1tk\xFD vzkaz; p\u0159ed odesl\xE1n\xEDm ov\u011B\u0159 p\u0159\xEDjemce, term\xEDn a hlavn\xED sd\u011Blen\xED."],"Dev\xEDtka hol\xED":["Chr\xE1n\xED t\u011B tvoje ostra\u017Eitost, nebo u\u017E vy\u010Derp\xE1v\xE1?","P\u0159iprav si jednu rozumnou pojistku a pak si dovol od \xFAkolu na chv\xEDli odstoupit."],"Des\xEDtka hol\xED":["Kterou z\xE1t\u011B\u017E nemus\xED\u0161 n\xE9st celou?","Jeden \xFAkol p\u0159edej, rozd\u011Bl na men\u0161\xED \u010D\xE1sti nebo u n\u011Bj vyjednej pozd\u011Bj\u0161\xED term\xEDn."],"P\xE1\u017Ee hol\xED":["Co t\u011B zaj\xEDm\xE1 bez pot\u0159eby hned vyniknout?","V\u011Bnuj chv\xEDli za\u010D\xE1te\u010Dnick\xE9mu pokusu a sleduj, co t\u011B na n\u011Bm bav\xED."],"Ryt\xED\u0159 hol\xED":["Kam t\u011B \u017Eene nad\u0161en\xED a co pot\u0159ebuje domyslet?","Ne\u017E se do n\u011B\u010Deho vrhne\u0161, stanov jeden dosa\u017Eiteln\xFD c\xEDl a jednu bezpe\u010Dnou hranici."],"Kr\xE1lovna hol\xED":["Kde se m\u016F\u017Ee\u0161 projevit bez p\u0159edv\xE1d\u011Bn\xED?","Sd\xEDlej jeden vlastn\xED n\xE1pad jednodu\u0161e a nech ostatn\xEDm prostor na reakci."],"Kr\xE1l hol\xED":["Jak\xFD sm\u011Br od tebe ostatn\xED pot\u0159ebuj\xED sly\u0161et?","Pojmenuj z\xE1m\u011Br, prvn\xED krok a to, za co p\u0159eb\xEDr\xE1\u0161 odpov\u011Bdnost."],"Eso poh\xE1r\u016F":["Pro jak\xFD pocit chce\u0161 ud\u011Blat m\xEDsto?","Zastav se u jedn\xE9 p\u0159\xEDjemn\xE9 chv\xEDle a napi\u0161, co ji umo\u017Enilo."],"Dvojka poh\xE1r\u016F":["Je prostor pro oba pohledy?","V jednom rozhovoru se nejprve zeptej na pot\u0159ebu druh\xE9ho a pak pojmenuj svou."],"Trojka poh\xE1r\u016F":["S k\xFDm chce\u0161 sd\xEDlet n\u011Bco oby\u010Dejn\u011B hezk\xE9ho?","Ozvi se n\u011Bkomu bl\xEDzk\xE9mu s konkr\xE9tn\xEDm pozv\xE1n\xEDm na kr\xE1tk\xE9 setk\xE1n\xED nebo hovor."],"\u010Cty\u0159ka poh\xE1r\u016F":["Pot\u0159ebuje\u0161 novou nab\xEDdku, nebo chv\xEDli odstupu?","Ne\u017E n\u011Bco odm\xEDtne\u0161, odd\u011Bl nez\xE1jem o nab\xEDdku od vlastn\xED moment\xE1ln\xED \xFAnavy."],"P\u011Btka poh\xE1r\u016F":["Co z\u016Fst\xE1v\xE1 oporou vedle zklam\xE1n\xED?","Pojmenuj ztr\xE1tu bez zleh\u010Dov\xE1n\xED a jednu konkr\xE9tn\xED dostupnou oporu pro dne\u0161ek."],"\u0160estka poh\xE1r\u016F":["Co si chce\u0161 vz\xEDt z minulosti a co v n\xED nechat?","Vra\u0165 se k jedn\xE9 vzpom\xEDnce a odd\u011Bl jej\xED p\u0159\xEDjemn\xFD pocit od dne\u0161n\xEDch skute\u010Dn\xFDch podm\xEDnek."],"Sedmi\u010Dka poh\xE1r\u016F":["Kter\xE1 mo\u017Enost m\xE1 i konkr\xE9tn\xED obrysy?","Z mnoha p\u0159edstav vyber jednu a zjisti prvn\xED ov\u011B\u0159iteln\xFD \xFAdaj, kter\xFD pro ni pot\u0159ebuje\u0161."],"Osmi\u010Dka poh\xE1r\u016F":["Kde z\u016Fst\xE1v\xE1\u0161 jen ze zvyku?","Sepi\u0161 si, co by se muselo zm\u011Bnit, aby pro tebe pokra\u010Dov\xE1n\xED m\u011Blo smysl. Rozhodnut\xED nemus\xED p\u0159ij\xEDt hned."],"Dev\xEDtka poh\xE1r\u016F":["Co je pro tebe dost pr\xE1v\u011B te\u010F?","V\u0161imni si jedn\xE9 napln\u011Bn\xE9 pot\u0159eby, ne\u017E za\u010Dne\u0161 p\u0159id\xE1vat dal\u0161\xED p\u0159\xE1n\xED."],"Des\xEDtka poh\xE1r\u016F":["Jak vypad\xE1 bl\xEDzkost v b\u011B\u017En\xE9m dni?","Ud\u011Blej mal\xFD spole\u010Dn\xFD krok, kter\xFD podporuje domov nebo vztahy bez po\u017Eadavku na dokonalou harmonii."],"P\xE1\u017Ee poh\xE1r\u016F":["Kter\xFD jemn\xFD podn\u011Bt stoj\xED za pozornost?","Zapi\u0161 si n\xE1pad nebo pocit bez okam\u017Eit\xE9ho posuzov\xE1n\xED a pozd\u011Bji se k n\u011Bmu vra\u0165."],"Ryt\xED\u0159 poh\xE1r\u016F":["Odpov\xEDdaj\xED hezk\xE1 slova tak\xE9 \u010Din\u016Fm?","U jednoho slibu si vyjasni konkr\xE9tn\xED podobu a term\xEDn. Plat\xED to i pro vlastn\xED sliby."],"Kr\xE1lovna poh\xE1r\u016F":["Dok\xE1\u017Ee\u0161 naslouchat bez p\u0159eb\xEDr\xE1n\xED ciz\xEDho probl\xE9mu?","Nab\xEDdni druh\xE9mu pozornost a zeptej se, zda chce vyslechnout, nebo hledat \u0159e\u0161en\xED."],"Kr\xE1l poh\xE1r\u016F":["Jak pojmenovat emoci a z\u016Fstat v\u011Bcn\u011B v kontaktu?","\u0158ekni, co pro\u017E\xEDv\xE1\u0161, jednou v\u011Btou bez obvi\u0148ov\xE1n\xED a navrhni konkr\xE9tn\xED dal\u0161\xED krok."],"Eso me\u010D\u016F":["Jakou ot\xE1zku pot\u0159ebuje\u0161 jasn\u011B formulovat?","Napi\u0161 hlavn\xED ot\xE1zku bez vedlej\u0161\xEDch p\u0159\xEDb\u011Bh\u016F a zjisti, jak\xFD \xFAdaj ti chyb\xED k odpov\u011Bdi."],"Dvojka me\u010D\u016F":["Kterou \u010D\xE1st rozhodnut\xED zat\xEDm nechce\u0161 vid\u011Bt?","Pojmenuj, jakou informaci pot\u0159ebuje\u0161 pro dal\u0161\xED krok a kde ji m\u016F\u017Ee\u0161 z\xEDskat."],"Trojka me\u010D\u016F":["Co pot\u0159ebuje\u0161 uznat m\xEDsto rychl\xE9 n\xE1plasti?","Dovol si pojmenovat zklam\xE1n\xED a pro dne\u0161ek si vyber jednu laskavou, praktickou oporu."],"\u010Cty\u0159ka me\u010D\u016F":["Co m\u016F\u017Ee bezpe\u010Dn\u011B po\u010Dkat?","Vyhra\u010F si kr\xE1tk\xFD neru\u0161en\xFD odpo\u010Dinek a odlo\u017E jeden nepodstatn\xFD po\u017Eadavek."],"P\u011Btka me\u010D\u016F":["Stoj\xED v\xEDt\u011Bzstv\xED v tomto sporu za jeho cenu?","Zva\u017E, zda m\u016F\u017Ee\u0161 jednu debatu ukon\u010Dit dohodou o dal\u0161\xEDm postupu m\xEDsto posledn\xEDho slova."],"\u0160estka me\u010D\u016F":["Co ti usnadn\xED p\u0159echod do klidn\u011Bj\u0161\xEDho re\u017Eimu?","P\u0159iprav si jednu praktickou v\u011Bc pro zm\u011Bnu, kterou u\u017E m\xE1\u0161 rozmy\u0161lenou."],"Sedmi\u010Dka me\u010D\u016F":["Co si zaslou\u017E\xED ov\u011B\u0159en\xED m\xEDsto domn\u011Bnek?","Ov\u011B\u0159 jeden nejasn\xFD \xFAdaj z p\u0159\xEDm\xE9ho zdroje. Karta sama nedokazuje podvod ani nev\u011Bru."],"Osmi\u010Dka me\u010D\u016F":["Kter\xE9 omezen\xED je skute\u010Dn\xE9 a kter\xE9 p\u0159edpokl\xE1d\xE1\u0161?","U jedn\xE9 p\u0159ek\xE1\u017Eky najdi malou mo\u017Enost jedn\xE1n\xED nebo \u010Dlov\u011Bka, kter\xE9ho se lze doptat."],"Dev\xEDtka me\u010D\u016F":["Co je obava a co u\u017E vy\u017Eaduje konkr\xE9tn\xED \u0159e\u0161en\xED?","Zapi\u0161 jednu starost a nejbli\u017E\u0161\xED rozumn\xFD krok. Pokud t\u011B obavy dlouhodob\u011B zat\u011B\u017Euj\xED, zva\u017E odbornou podporu."],"Des\xEDtka me\u010D\u016F":["Co u\u017E nen\xED pot\u0159eba znovu otev\xEDrat?","U uzav\u0159en\xE9 situace si poznamenej pou\u010Den\xED a jednu v\u011Bc, kter\xE1 pom\u016F\u017Ee zvl\xE1dnout dne\u0161ek."],"P\xE1\u017Ee me\u010D\u016F":["Na co je lep\u0161\xED se doptat ne\u017E rychle soudit?","Polo\u017E jednu p\u0159esnou ot\xE1zku a vyslechni odpov\u011B\u010F a\u017E do konce."],"Ryt\xED\u0159 me\u010D\u016F":["Je rychlost odpov\u011Bdi d\u016Fle\u017Eit\u011Bj\u0161\xED ne\u017E jej\xED p\u0159esnost?","P\u0159ed odesl\xE1n\xEDm ostr\xE9 zpr\xE1vy zkontroluj fakta a vynech jednu domn\u011Bnku o \xFAmyslech druh\xE9ho."],"Kr\xE1lovna me\u010D\u016F":["Jak \u0159\xEDct pravdu jasn\u011B a bez zbyte\u010Dn\xE9ho zran\u011Bn\xED?","Odd\u011Bl pozorov\xE1n\xED od hodnocen\xED \u010Dlov\u011Bka a formuluj jeden srozumiteln\xFD po\u017Eadavek."],"Kr\xE1l me\u010D\u016F":["Podle \u010Deho chce\u0161 rozhodovat?","Sepi\u0161 dv\u011B konkr\xE9tn\xED krit\xE9ria pro aktu\xE1ln\xED rozhodnut\xED a pou\u017E\xEDvej je pro v\u0161echny mo\u017Enosti stejn\u011B."],"Eso pent\xE1kl\u016F":["Jak m\u016F\u017Ee n\xE1pad z\xEDskat hmatateln\xFD z\xE1klad?","Ur\u010Di jednu dostupnou v\u011Bc, \u010Das nebo dovednost, se kterou m\u016F\u017Ee\u0161 za\u010D\xEDt."],"Dvojka pent\xE1kl\u016F":["Kolik v\u011Bc\xED je\u0161t\u011B zvl\xE1dne\u0161 udr\u017Eet v pohybu?","Srovnej dv\u011B dne\u0161n\xED priority a jednu m\xE9n\u011B d\u016Fle\u017Eitou \u010Dinnost p\u0159esu\u0148 nebo zru\u0161."],"Trojka pent\xE1kl\u016F":["\u010C\xED dovednost m\u016F\u017Ee doplnit tu tvou?","U spole\u010Dn\xE9ho \xFAkolu si s ostatn\xEDmi ujasni, kdo co p\u0159iprav\xED a jak poznat hotov\xFD v\xFDsledek."],"\u010Cty\u0159ka pent\xE1kl\u016F":["Co chr\xE1n\xED\u0161 rozumn\u011B a co u\u017E sv\xEDr\xE1\u0161 p\u0159\xEDli\u0161?","U jedn\xE9 z\xE1soby \u010Dasu, pen\u011Bz \u010Di v\u011Bc\xED pojmenuj \xFA\u010Del. Ned\u011Blej finan\u010Dn\xED rozhodnut\xED podle karty."],"P\u011Btka pent\xE1kl\u016F":["Jak\xE1 konkr\xE9tn\xED pomoc je pro tebe dostupn\xE1?","Zjisti jeden skute\u010Dn\xFD zdroj podpory a po\u017Eadavky pro jeho vyu\u017Eit\xED; nemus\xED\u0161 na obt\xED\u017Enou situaci z\u016Fstat bez pomoci."],"\u0160estka pent\xE1kl\u016F":["Je d\xE1v\xE1n\xED a p\u0159ij\xEDm\xE1n\xED srozumiteln\xE9 ob\u011Bma stran\xE1m?","P\u0159i nab\xEDdce pomoci si s druhou stranou ujasni jej\xED rozsah a podm\xEDnky m\xEDsto tich\xFDch o\u010Dek\xE1v\xE1n\xED."],"Sedmi\u010Dka pent\xE1kl\u016F":["Co u\u017E roste a co pot\u0159ebuje upravit?","Zkontroluj jeden dlouhodob\xFD \xFAkol podle skute\u010Dn\xE9ho pokroku, ne podle dne\u0161n\xED netrp\u011Blivosti."],"Osmi\u010Dka pent\xE1kl\u016F":["Kter\xFD detail se zlep\u0161\xED pravideln\xFDm procvi\u010Den\xEDm?","V\u011Bnuj \u010Dtvrt hodiny jedn\xE9 dovednosti a porovnej konkr\xE9tn\xED detail s p\u0159edchoz\xEDm pokusem."],"Dev\xEDtka pent\xE1kl\u016F":["Kter\xFD v\xFDsledek vznikl d\xEDky tv\xE9 vlastn\xED p\xE9\u010Di?","Oce\u0148 jeden konkr\xE9tn\xED v\xFDsledek sv\xE9 pr\xE1ce a dop\u0159ej si mo\u017Enost ho chv\xEDli pou\u017E\xEDvat, ne jen vylep\u0161ovat."],"Des\xEDtka pent\xE1kl\u016F":["Co m\xE1 smysl udr\u017Eet i pro dal\u0161\xED obdob\xED?","U spole\u010Dn\xE9ho z\xE1zem\xED nebo projektu zapi\u0161 jednu dohodu, kter\xE1 usnadn\xED dlouhodob\xE9 fungov\xE1n\xED."],"P\xE1\u017Ee pent\xE1kl\u016F":["Co se chce\u0161 nau\u010Dit prakticky, krok po kroku?","Vyber mal\xFD u\u010Debn\xED \xFAkol a \u010Das, kdy ho skute\u010Dn\u011B zkus\xED\u0161 m\xEDsto dal\u0161\xEDho shroma\u017E\u010Fov\xE1n\xED materi\xE1l\u016F."],"Ryt\xED\u0159 pent\xE1kl\u016F":["Kde bude spolehlivost cenn\u011Bj\u0161\xED ne\u017E zrychlov\xE1n\xED?","Dokon\u010Di jeden b\u011B\u017En\xFD krok pe\u010Dliv\u011B a zaznamenej, na co m\xE1 p\u0159\xED\u0161t\u011B nav\xE1zat."],"Kr\xE1lovna pent\xE1kl\u016F":["Co ti v b\u011B\u017En\xE9m z\xE1zem\xED usnadn\xED den?","Postarej se o jednu konkr\xE9tn\xED pot\u0159ebu sv\xE9ho prostoru nebo re\u017Eimu bez n\xE1roku na dokonalost."],"Kr\xE1l pent\xE1kl\u016F":["O co se op\xEDr\xE1 tvoje praktick\xE9 rozhodnut\xED?","P\u0159ed z\xE1vazkem si ov\u011B\u0159 dostupn\xE9 prost\u0159edky, \u010Das a odpov\u011Bdnost. Karta nenahrazuje odbornou radu."]};var r={Bl\u00E1zen:{image:"img/tarot-v2/tarot_blazen.webp",meaning:"Za\u010D\xEDt mal\xFDm krokem",interpretation:"Bl\xE1zen m\u016F\u017Ee otev\u0159\xEDt chu\u0165 vyzkou\u0161et n\u011Bco nov\xE9ho."},M\u00E1g:{image:"img/tarot-v2/tarot_mag.webp",meaning:"Pou\u017E\xEDt dostupn\xE9 mo\u017Enosti",interpretation:"M\xE1g m\u016F\u017Ee p\u0159ipomenout, \u017Ee n\xE1pad pot\u0159ebuje konkr\xE9tn\xED n\xE1stroj a jedn\xE1n\xED."},Velekn\u011B\u017Eka:{image:"img/tarot-v2/tarot_veleknezka.webp",meaning:"Vn\xEDmat dojem a ov\u011B\u0159it souvislosti",interpretation:"Velekn\u011B\u017Eka m\u016F\u017Ee otev\u0159\xEDt prostor pro tich\xFD post\u0159eh a ot\xE1zku, kterou zat\xEDm neum\xED\u0161 p\u0159esn\u011B vyslovit."},C\u00EDsa\u0159ovna:{image:"img/tarot-v2/tarot_cisarovna.webp",meaning:"P\xE9\u010De, kter\xE1 m\xE1 prostor",interpretation:"C\xEDsa\u0159ovna m\u016F\u017Ee p\u0159ipomenout p\xE9\u010Di, tvo\u0159ivost a podm\xEDnky, v nich\u017E se n\u011B\u010Demu dob\u0159e da\u0159\xED."},C\u00EDsa\u0159:{image:"img/tarot-v2/tarot_cisar.webp",meaning:"Uspo\u0159\xE1dat odpov\u011Bdnost",interpretation:"C\xEDsa\u0159 m\u016F\u017Ee p\u0159ipomenout jasn\xFD r\xE1mec a rozd\u011Blen\xED odpov\u011Bdnosti."},Velekn\u011Bz:{image:"img/tarot-v2/tarot_veleknez.webp",meaning:"Rozum\u011Bt pravidl\u016Fm a veden\xED",interpretation:"Velekn\u011Bz m\u016F\u017Ee nab\xEDdnout t\xE9ma p\u0159ed\xE1van\xE9 zku\u0161enosti, pravidel a rady n\u011Bkoho dal\u0161\xEDho."},Milenci:{image:"img/tarot-v2/tarot_milenci.webp",meaning:"P\u0159ita\u017Elivost a spole\u010Dn\xE1 volba",interpretation:"Milenci spojuj\xED p\u0159ita\u017Elivost, volbu a hodnoty."},V\u016Fz:{image:"img/tarot-v2/tarot_vuz.webp",meaning:"D\xE1t \xFAsil\xED jasn\xFD sm\u011Br",interpretation:"V\u016Fz m\u016F\u017Ee p\u0159ipomenout soust\u0159ed\u011Bn\xED na jeden c\xEDl a slad\u011Bn\xED r\u016Fzn\xFDch po\u017Eadavk\u016F."},S\u00EDla:{image:"img/tarot-v2/tarot_sila.webp",meaning:"Reagovat pevn\u011B a trp\u011Bliv\u011B",interpretation:"S\xEDla m\u016F\u017Ee p\u0159ipomenout jedn\xE1n\xED, kter\xE9 je pevn\xE9 bez zbyte\u010Dn\xE9ho n\xE1tlaku."},Poustevn\u00EDk:{image:"img/tarot-v2/tarot_poustevnik.webp",meaning:"Z\xEDskat prostor pro vlastn\xED ot\xE1zku",interpretation:"Poustevn\xEDk m\u016F\u017Ee p\u0159ipomenout chv\xEDli, kdy pot\u0159ebuje\u0161 srovnat vlastn\xED pohled."},"Kolo \u0161t\u011Bst\xED":{image:"img/tarot-v2/tarot_kolo_stesti.webp",meaning:"P\u0159izp\u016Fsobit pl\xE1n zm\u011Bn\u011B",interpretation:"Kolo \u0161t\u011Bst\xED m\u016F\u017Ee otev\u0159\xEDt t\xE9ma prom\u011Bnliv\xFDch okolnost\xED."},Spravedlnost:{image:"img/tarot-v2/tarot_spravedlnost.webp",meaning:"Porovnat podklady a dopady",interpretation:"Spravedlnost m\u016F\u017Ee p\u0159ipomenout rozhodnut\xED, kter\xE9 um\xED\u0161 vysv\u011Btlit podle podklad\u016F a dopadu na druh\xE9."},Viselec:{image:"img/tarot-v2/tarot_viselec.webp",meaning:"Pod\xEDvat se z jin\xE9ho \xFAhlu",interpretation:"Viselec m\u016F\u017Ee p\u0159ipomenout p\u0159eru\u0161en\xED obvykl\xE9ho postupu a jin\xFD pohled."},Smrt:{image:"img/tarot-v2/tarot_smrt.webp",meaning:"Pojmenovat ukon\u010Den\xED a zm\u011Bnu",interpretation:"Karta Smrt m\u016F\u017Ee nab\xEDdnout symbolick\xE9 t\xE9ma uzav\u0159en\xED a prom\u011Bny."},M\u00EDrnost:{image:"img/tarot-v2/tarot_mirnost.webp",meaning:"Sladit tempo a mo\u017Enosti",interpretation:"M\xEDrnost m\u016F\u017Ee p\u0159ipomenout rozumn\xE9 d\xE1vkov\xE1n\xED \xFAsil\xED a spojen\xED r\u016Fzn\xFDch pot\u0159eb."},\u010E\u00E1bel:{image:"img/tarot-v2/tarot_dabel.webp",meaning:"Rozpoznat tlak a vlastn\xED mo\u017Enosti",interpretation:"\u010E\xE1bel m\u016F\u017Ee nab\xEDdnout ot\xE1zku na tlak, z\xE1vazek nebo opakovan\xFD vzorec."},V\u011B\u017E:{image:"img/tarot-v2/tarot_vez.webp",meaning:"Reagovat na naru\u0161en\xFD pl\xE1n",interpretation:"V\u011B\u017E m\u016F\u017Ee nab\xEDdnout obraz pl\xE1nu, jeho\u017E p\u0159edpoklady se zm\u011Bnily."},Hv\u011Bzda:{image:"img/tarot-v2/tarot_hvezda.webp",meaning:"Naj\xEDt konkr\xE9tn\xED oporu nad\u011Bje",interpretation:"Hv\u011Bzda m\u016F\u017Ee p\u0159ipomenout nad\u011Bji, inspiraci a n\u011Bco, o co se m\u016F\u017Ee\u0161 op\u0159\xEDt u\u017E te\u010F."},Luna:{image:"img/tarot-v2/tarot_luna.webp",meaning:"Rozli\u0161it dojem a chyb\u011Bj\xEDc\xED informaci",interpretation:"Luna (M\u011Bs\xEDc) m\u016F\u017Ee p\u0159ipomenout nejistotu, dojem a to, co zat\xEDm nem\xE1 jasn\xE9 souvislosti."},Slunce:{image:"img/tarot-v2/tarot_slunce.webp",meaning:"Radost, jasnost a otev\u0159enost",interpretation:"Slunce je obraz radosti, jasnosti a otev\u0159enosti."},Soud:{image:"img/tarot-v2/tarot_soud.webp",meaning:"Zhodnotit zku\u0161enost a zvolit pokra\u010Dov\xE1n\xED",interpretation:"Soud (Soudce) m\u016F\u017Ee p\u0159ipomenout bilanci zku\u0161enosti a rozhodnut\xED, jak pokra\u010Dovat."},Sv\u011Bt:{image:"img/tarot-v2/tarot_svet.webp",meaning:"Dokon\u010Dit a pojmenovat v\xFDsledek",interpretation:"Sv\u011Bt m\u016F\u017Ee p\u0159ipomenout dokon\u010Den\xED \xFAkolu, propojen\xED zku\u0161enost\xED a prostor v\u0161imnout si v\xFDsledku."},"Eso hol\xED":{image:"img/tarot-v2/tarot_eso_holi.webp",meaning:"Jiskra, kter\xE1 \u010Dek\xE1 na tvar",interpretation:"Eso hol\xED otev\xEDr\xE1 t\xE9ma prvotn\xEDho z\xE1palu: n\xE1pad, chu\u0165 n\u011Bco zkusit nebo nov\xE1 tv\u016Fr\u010D\xED energie."},"Dvojka hol\xED":{image:"img/tarot-v2/tarot_dvojka_holi.webp",meaning:"V\xFDhled a rozhodnut\xED o sm\u011Bru",interpretation:"Dvojka hol\xED stoj\xED mezi zn\xE1m\xFDm z\xE1zem\xEDm a mo\u017Enost\xED roz\u0161\xED\u0159it obzor."},"Trojka hol\xED":{image:"img/tarot-v2/tarot_trojka_holi.webp",meaning:"Rozvoj, kter\xFD pot\u0159ebuje trp\u011Blivost",interpretation:"Trojka hol\xED navazuje na rozhodnut\xED a obrac\xED pozornost k tomu, jak se z\xE1m\u011Br setk\xE1 se sv\u011Btem."},"\u010Cty\u0159ka hol\xED":{image:"img/tarot-v2/tarot_ctyrka_holi.webp",meaning:"Sd\xEDlen\xE1 radost a pevn\xFD z\xE1klad",interpretation:"\u010Cty\u0159ka hol\xED zachycuje chv\xEDli, kdy lze n\u011Bco oslavit nebo se op\u0159\xEDt o spole\u010Dn\xE9 z\xE1zem\xED."},"P\u011Btka hol\xED":{image:"img/tarot-v2/tarot_petka_holi.webp",meaning:"T\u0159en\xED, sout\u011B\u017E a r\u016Fzn\xE9 n\xE1pady",interpretation:"P\u011Btka hol\xED d\xE1v\xE1 prostor nesouhlasu a soupe\u0159en\xED."},"\u0160estka hol\xED":{image:"img/tarot-v2/tarot_sestka_holi.webp",meaning:"Uzn\xE1n\xED a viditelnost v\xFDsledku",interpretation:"\u0160estka hol\xED se poj\xED s uzn\xE1n\xEDm, ve\u0159ejn\xFDm v\xFDsledkem nebo chv\xEDl\xED, kdy si v\u0161imne\u0161 vlastn\xEDho pokroku."},"Sedmi\u010Dka hol\xED":{image:"img/tarot-v2/tarot_sedmicka_holi.webp",meaning:"Obh\xE1jit hranici bez vy\u010Derp\xE1n\xED",interpretation:"Sedmi\u010Dka hol\xED zobrazuje pot\u0159ebu st\xE1t si za stanoviskem, zvl\xE1\u0161\u0165 kdy\u017E na tebe p\u016Fsob\xED tlak."},"Osmi\u010Dka hol\xED":{image:"img/tarot-v2/tarot_osmicka_holi.webp",meaning:"Rychlost, zpr\xE1va a na\u010Dasov\xE1n\xED",interpretation:"Osmi\u010Dka hol\xED p\u0159ipom\xEDn\xE1 rychl\xFD sled ud\xE1lost\xED, zpr\xE1v nebo \xFAkol\u016F."},"Dev\xEDtka hol\xED":{image:"img/tarot-v2/tarot_devitka_holi.webp",meaning:"Vytrvalost s prostorem na oddech",interpretation:"Dev\xEDtka hol\xED p\u0159edstavuje zku\u0161enost, kter\xE1 t\u011B nau\u010Dila hl\xEDdat si s\xEDly."},"Des\xEDtka hol\xED":{image:"img/tarot-v2/tarot_desitka_holi.webp",meaning:"Z\xE1t\u011B\u017E, kterou lze p\u0159erozd\u011Blit",interpretation:"Des\xEDtka hol\xED ukazuje mnoho povinnost\xED nar\xE1z."},"P\xE1\u017Ee hol\xED":{image:"img/tarot-v2/tarot_paze_holi.webp",meaning:"Zv\u011Bdavost a prvn\xED pokus",interpretation:"P\xE1\u017Ee hol\xED je obrazem za\u010D\xE1te\u010Dnick\xE9 zv\u011Bdavosti, kter\xE1 chce prozkoumat nov\xFD sm\u011Br."},"Ryt\xED\u0159 hol\xED":{image:"img/tarot-v2/tarot_rytir_holi.webp",meaning:"Tah na branku a jeho cena",interpretation:"Ryt\xED\u0159 hol\xED p\u0159in\xE1\u0161\xED odvahu vyrazit a siln\xFD tah k c\xEDli."},"Kr\xE1lovna hol\xED":{image:"img/tarot-v2/tarot_kralovna_holi.webp",meaning:"Sebejistota, kter\xE1 nech\xE1v\xE1 prostor",interpretation:"Kr\xE1lovna hol\xED spojuje tvo\u0159ivost, v\u0159elost a sebejist\xE9 vystupov\xE1n\xED."},"Kr\xE1l hol\xED":{image:"img/tarot-v2/tarot_kral_holi.webp",meaning:"Vize, odpov\u011Bdnost a sm\u011Br",interpretation:"Kr\xE1l hol\xED p\u0159edstavuje schopnost spojit vizi s rozhodnut\xEDm a n\xE9st za n\u011Bj odpov\u011Bdnost."},"Eso poh\xE1r\u016F":{image:"img/tarot-v2/tarot_eso_poharu.webp",meaning:"Otev\u0159enost bez sp\u011Bchu",interpretation:"Eso poh\xE1r\u016F otev\xEDr\xE1 prostor pro cit, tvo\u0159ivost a nov\xFD za\u010D\xE1tek bez z\xE1ruky v\xFDsledku."},"Dvojka poh\xE1r\u016F":{image:"img/tarot-v2/tarot_dvojka_poharu.webp",meaning:"Setk\xE1n\xED a vz\xE1jemn\xE1 odezva",interpretation:"Dvojka poh\xE1r\u016F p\u0159edstavuje setk\xE1n\xED, vz\xE1jemnou odezvu a prostor pro jasnou dohodu."},"Trojka poh\xE1r\u016F":{image:"img/tarot-v2/tarot_trojka_poharu.webp",meaning:"Radost, kter\xE1 se sd\xEDl\xED",interpretation:"Trojka poh\xE1r\u016F p\u0159ipom\xEDn\xE1 p\u0159\xE1telstv\xED, spole\u010Dnou radost a podporu okol\xED."},"\u010Cty\u0159ka poh\xE1r\u016F":{image:"img/tarot-v2/tarot_ctyrka_poharu.webp",meaning:"V\u0161imnout si, co je na dosah",interpretation:"\u010Cty\u0159ka poh\xE1r\u016F vyb\xEDz\xED rozli\u0161it skute\u010Dn\xFD nez\xE1jem od \xFAnavy nebo zklam\xE1n\xED."},"P\u011Btka poh\xE1r\u016F":{image:"img/tarot-v2/tarot_petka_poharu.webp",meaning:"Ztr\xE1ta i to, co z\u016Fst\xE1v\xE1",interpretation:"P\u011Btka poh\xE1r\u016F uzn\xE1v\xE1 zklam\xE1n\xED a postupn\u011B roz\u0161i\u0159uje pohled i na to, co z\u016Fst\xE1v\xE1."},"\u0160estka poh\xE1r\u016F":{image:"img/tarot-v2/tarot_sestka_poharu.webp",meaning:"Vzpom\xEDnka v p\u0159\xEDtomn\xE9m \u010Dase",interpretation:"\u0160estka poh\xE1r\u016F propojuje vzpom\xEDnky s ot\xE1zkou, co m\xE1 smysl v p\u0159\xEDtomnosti."},"Sedmi\u010Dka poh\xE1r\u016F":{image:"img/tarot-v2/tarot_sedmicka_poharu.webp",meaning:"Mo\u017Enosti pot\u0159ebuj\xED ov\u011B\u0159en\xED",interpretation:"Sedmi\u010Dka poh\xE1r\u016F pom\xE1h\xE1 odd\u011Blit l\xE1kav\xE9 p\u0159edstavy od mo\u017Enost\xED s ov\u011B\u0159iteln\xFDmi podm\xEDnkami."},"Osmi\u010Dka poh\xE1r\u016F":{image:"img/tarot-v2/tarot_osmicka_poharu.webp",meaning:"Odej\xEDt od toho, co nenapl\u0148uje",interpretation:"Osmi\u010Dka poh\xE1r\u016F otev\xEDr\xE1 ot\xE1zku, kdy situace p\u0159est\xE1v\xE1 napl\u0148ovat d\u016Fle\u017Eit\xE9 pot\u0159eby."},"Dev\xEDtka poh\xE1r\u016F":{image:"img/tarot-v2/tarot_devitka_poharu.webp",meaning:"Spokojenost bez p\u0159ehl\xED\u017Een\xED ceny",interpretation:"Dev\xEDtka poh\xE1r\u016F se pt\xE1 na osobn\xED spokojenost a cenu, kterou za ni plat\xED\u0161."},"Des\xEDtka poh\xE1r\u016F":{image:"img/tarot-v2/tarot_desitka_poharu.webp",meaning:"Spole\u010Dn\xE1 spokojenost a dohoda",interpretation:"Des\xEDtka poh\xE1r\u016F spojuje p\u0159edstavu soun\xE1le\u017Eitosti s konkr\xE9tn\xEDmi dohodami."},"P\xE1\u017Ee poh\xE1r\u016F":{image:"img/tarot-v2/tarot_paze_poharu.webp",meaning:"Citliv\xE1 zpr\xE1va a prvn\xED pokus",interpretation:"P\xE1\u017Ee poh\xE1r\u016F vyb\xEDz\xED k citliv\xE9mu prvn\xEDmu kroku a jasn\xE9mu vyj\xE1d\u0159en\xED."},"Ryt\xED\u0159 poh\xE1r\u016F":{image:"img/tarot-v2/tarot_rytir_poharu.webp",meaning:"Nab\xEDdka, kter\xE1 pot\u0159ebuje obsah",interpretation:"Ryt\xED\u0159 poh\xE1r\u016F spojuje citov\xE9 gesto s pot\u0159ebou jasn\xFDch podm\xEDnek."},"Kr\xE1lovna poh\xE1r\u016F":{image:"img/tarot-v2/tarot_kralovna_poharu.webp",meaning:"Empatie s vlastn\xEDmi hranicemi",interpretation:"Kr\xE1lovna poh\xE1r\u016F p\u0159ipom\xEDn\xE1 empatii, kter\xE1 neztr\xE1c\xED vlastn\xED hranice."},"Kr\xE1l poh\xE1r\u016F":{image:"img/tarot-v2/tarot_kral_poharu.webp",meaning:"Klidn\xE1 reakce v citov\xE9 situaci",interpretation:"Kr\xE1l poh\xE1r\u016F spojuje citovou vyrovnanost s jasnou a respektuj\xEDc\xED komunikac\xED."},"Eso me\u010D\u016F":{image:"img/tarot-v2/tarot_eso_mecu.webp",meaning:"Jasnost a p\u0159esn\xE1 ot\xE1zka",interpretation:"Eso me\u010D\u016F m\u016F\u017Ee p\u0159ipomenout jasnou ot\xE1zku, p\u0159esn\xE9 pojmenov\xE1n\xED a nov\xFD pohled."},"Dvojka me\u010D\u016F":{image:"img/tarot-v2/tarot_dvojka_mecu.webp",meaning:"Volba, kter\xE1 pot\u0159ebuje prostor",interpretation:"Dvojka me\u010D\u016F m\u016F\u017Ee otev\u0159\xEDt t\xE9ma v\xE1h\xE1n\xED mezi dv\u011Bma mo\u017Enostmi."},"Trojka me\u010D\u016F":{image:"img/tarot-v2/tarot_trojka_mecu.webp",meaning:"Pojmenovat zklam\xE1n\xED",interpretation:"Trojka me\u010D\u016F je v\xFDrazn\xFD obraz zklam\xE1n\xED nebo bolestiv\xE9ho rozhovoru."},"\u010Cty\u0159ka me\u010D\u016F":{image:"img/tarot-v2/tarot_ctyrka_mecu.webp",meaning:"Pauza p\u0159ed dal\u0161\xED reakc\xED",interpretation:"\u010Cty\u0159ka me\u010D\u016F m\u016F\u017Ee p\u0159ipomenout prostor mezi podn\u011Btem a reakc\xED."},"P\u011Btka me\u010D\u016F":{image:"img/tarot-v2/tarot_petka_mecu.webp",meaning:"Cena sporu",interpretation:"P\u011Btka me\u010D\u016F m\u016F\u017Ee otev\u0159\xEDt ot\xE1zku, co spor stoj\xED a \u010Deho j\xEDm chce\u0161 dos\xE1hnout."},"\u0160estka me\u010D\u016F":{image:"img/tarot-v2/tarot_sestka_mecu.webp",meaning:"P\u0159echod s konkr\xE9tn\xED oporou",interpretation:"\u0160estka me\u010D\u016F m\u016F\u017Ee p\u0159ipomenout p\u0159echod mezi zn\xE1mou situac\xED a n\u011B\u010D\xEDm nov\xFDm."},"Sedmi\u010Dka me\u010D\u016F":{image:"img/tarot-v2/tarot_sedmicka_mecu.webp",meaning:"Strategie a nevy\u0159\u010Den\xE9 v\u011Bci",interpretation:"Sedmi\u010Dka me\u010D\u016F m\u016F\u017Ee otev\u0159\xEDt t\xE9ma strategie, soukrom\xED a v\u011Bc\xED, kter\xE9 z\u016Fst\xE1vaj\xED nevy\u0159\u010Den\xE9."},"Osmi\u010Dka me\u010D\u016F":{image:"img/tarot-v2/tarot_osmicka_mecu.webp",meaning:"Rozli\u0161it omezen\xED",interpretation:"Osmi\u010Dka me\u010D\u016F m\u016F\u017Ee nab\xEDdnout obraz omezen\xED a nejistoty, kudy d\xE1l."},"Dev\xEDtka me\u010D\u016F":{image:"img/tarot-v2/tarot_devitka_mecu.webp",meaning:"Pojmenovat opakuj\xEDc\xED se obavu",interpretation:"Dev\xEDtka me\u010D\u016F m\u016F\u017Ee nab\xEDdnout obraz opakuj\xEDc\xED se starosti nebo nejistoty."},"Des\xEDtka me\u010D\u016F":{image:"img/tarot-v2/tarot_desitka_mecu.webp",meaning:"Konec podle skute\u010Dn\xFDch okolnost\xED",interpretation:"Des\xEDtka me\u010D\u016F m\u016F\u017Ee otev\u0159\xEDt t\xE9ma vy\u010Derp\xE1n\xED nebo nefunguj\xEDc\xEDch podm\xEDnek."},"P\xE1\u017Ee me\u010D\u016F":{image:"img/tarot-v2/tarot_paze_mecu.webp",meaning:"Zv\u011Bdavost a ov\u011B\u0159en\xED",interpretation:"P\xE1\u017Ee me\u010D\u016F m\u016F\u017Ee p\u0159ipomenout zv\u011Bdavost, prvn\xED ot\xE1zku a ov\u011B\u0159ov\xE1n\xED nov\xE9 informace."},"Ryt\xED\u0159 me\u010D\u016F":{image:"img/tarot-v2/tarot_rytir_mecu.webp",meaning:"Rychlost s rozvahou",interpretation:"Ryt\xED\u0159 me\u010D\u016F m\u016F\u017Ee otev\u0159\xEDt t\xE9ma rychl\xE9 reakce a p\u0159esn\xE9ho sm\u011Bru."},"Kr\xE1lovna me\u010D\u016F":{image:"img/tarot-v2/tarot_kralovna_mecu.webp",meaning:"Jasn\xE1 hranice v rozhovoru",interpretation:"Kr\xE1lovna me\u010D\u016F m\u016F\u017Ee p\u0159ipomenout jasnou \u0159e\u010D, vlastn\xED hranice a rozli\u0161ov\xE1n\xED fakt\u016F od dojm\u016F."},"Kr\xE1l me\u010D\u016F":{image:"img/tarot-v2/tarot_kral_mecu.webp",meaning:"Rozhodnut\xED podle krit\xE9ri\xED",interpretation:"Kr\xE1l me\u010D\u016F m\u016F\u017Ee nab\xEDdnout obraz rozhodov\xE1n\xED podle srozumiteln\xFDch krit\xE9ri\xED."},"Eso pent\xE1kl\u016F":{image:"img/tarot-v2/tarot_eso_pentaklu.webp",meaning:"Prvn\xED krok pot\u0159ebuje pevnou p\u016Fdu",interpretation:"Praktick\xFD za\u010D\xE1tek, kter\xFD stoj\xED za ov\u011B\u0159en\xED."},"Dvojka pent\xE1kl\u016F":{image:"img/tarot-v2/tarot_dvojka_pentaklu.webp",meaning:"Rytmus mezi z\xE1vazky",interpretation:"P\u0159izp\u016Fsobov\xE1n\xED tempa a priorit\xE1m."},"Trojka pent\xE1kl\u016F":{image:"img/tarot-v2/tarot_trojka_pentaklu.webp",meaning:"Kvalita roste ve spolupr\xE1ci",interpretation:"\u0158emeslo, zp\u011Btn\xE1 vazba a spole\u010Dn\xE9 \xFAsil\xED."},"\u010Cty\u0159ka pent\xE1kl\u016F":{image:"img/tarot-v2/tarot_ctyrka_pentaklu.webp",meaning:"Bezpe\u010D\xED bez sev\u0159en\xED",interpretation:"Hranice, jistota a ochota n\u011Bco pustit."},"P\u011Btka pent\xE1kl\u016F":{image:"img/tarot-v2/tarot_petka_pentaklu.webp",meaning:"Pojmenovat nedostatek a hledat oporu",interpretation:"Vylou\u010Den\xED, pot\u0159eby a mo\u017Enost po\u017E\xE1dat o pomoc."},"\u0160estka pent\xE1kl\u016F":{image:"img/tarot-v2/tarot_sestka_pentaklu.webp",meaning:"F\xE9rovost v d\xE1v\xE1n\xED a p\u0159ij\xEDm\xE1n\xED",interpretation:"Rovnov\xE1ha pomoci, odm\u011Bny a z\xE1vazk\u016F."},"Sedmi\u010Dka pent\xE1kl\u016F":{image:"img/tarot-v2/tarot_sedmicka_pentaklu.webp",meaning:"Zhodnotit, co u\u017E roste",interpretation:"Trp\u011Bliv\xE9 vyhodnocen\xED vlo\u017Een\xE9 pr\xE1ce."},"Osmi\u010Dka pent\xE1kl\u016F":{image:"img/tarot-v2/tarot_osmicka_pentaklu.webp",meaning:"Mistrovstv\xED z opakov\xE1n\xED",interpretation:"Praxe, soust\u0159ed\u011Bn\xED a smyslupln\xE1 oprava."},"Dev\xEDtka pent\xE1kl\u016F":{image:"img/tarot-v2/tarot_devitka_pentaklu.webp",meaning:"Samostatnost s prostorem pro radost",interpretation:"Vlastn\xED prostor, v\xFDsledky a jejich udr\u017Eov\xE1n\xED."},"Des\xEDtka pent\xE1kl\u016F":{image:"img/tarot-v2/tarot_desitka_pentaklu.webp",meaning:"Z\xE1zem\xED, kter\xE9 se sd\xEDl\xED",interpretation:"Rodinn\xE9 dohody a dlouhodob\xE9 z\xE1zem\xED."},"P\xE1\u017Ee pent\xE1kl\u016F":{image:"img/tarot-v2/tarot_paze_pentaklu.webp",meaning:"Zv\u011Bdavost p\u0159ev\xE9st do praxe",interpretation:"U\u010Den\xED, prvn\xED pokus a realistick\xFD za\u010D\xE1tek."},"Ryt\xED\u0159 pent\xE1kl\u016F":{image:"img/tarot-v2/tarot_rytir_pentaklu.webp",meaning:"Vytrvalost, kter\xE1 kontroluje sm\u011Br",interpretation:"Spolehliv\xE9 tempo s prostorem pro \xFApravy."},"Kr\xE1lovna pent\xE1kl\u016F":{image:"img/tarot-v2/tarot_kralovna_pentaklu.webp",meaning:"P\xE9\u010De, kter\xE1 zahrnuje i tebe",interpretation:"Praktick\xE1 p\xE9\u010De a udr\u017Eiteln\xE9 ka\u017Edodenn\xED z\xE1zem\xED."},"Kr\xE1l pent\xE1kl\u016F":{image:"img/tarot-v2/tarot_kral_pentaklu.webp",meaning:"Zdroje spravovat odpov\u011Bdn\u011B",interpretation:"Odpov\u011Bdnost za zdroje, veden\xED a udr\u017Eiteln\xFD pl\xE1n."}};function p(o=new Date){let e=new Intl.DateTimeFormat("en-CA",{timeZone:"Europe/Prague",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(o),t=a=>e.find(n=>n.type===a).value;return`${t("year")}-${t("month")}-${t("day")}`}function l(o,e=new Date){let t=p(e),a=0;for(let n=0;n<t.length;n++)a=(a<<5)-a+t.charCodeAt(n)|0;return Math.abs(a)%o}function j(o){let e=i[o];if(!e||!r[o])throw new Error("Daily card practice unavailable");return{question:e[0],action:e[1],observation:r[o].interpretation,meaning:r[o].meaning}}export{l as getDailyCardIndex,j as getDailyCardPractice,p as getPragueDateKey};
